target.css:
:root {
  --ink: #17243a;
  --muted: #69778b;
  --surface: #ffffff;
  --soft: #f4f7fa;
  --line: #dbe3eb;
  --navy: #263a61;
  --lime: #b7ed63;
  --lime-ink: #274219;
  --amber: #ffca69;
  --amber-ink: #6c4700;
  --green: #42aa78;
}

.service-panel {
  box-sizing: border-box;
  width: 500px;
  overflow: hidden;
  color: var(--ink);
  background: var(--surface);
  border: 1px solid var(--line);
  border-radius: 18px;
}

.topbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 13px 16px 12px;
  background: var(--navy);
}

.title-block p,
.title-block h1,
.car-header h2,
.dispatch-header h2,
.panel-footer p,
.arrival-note {
  margin: 0;
}

.eyebrow {
  color: var(--lime);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.title-block h1 {
  margin-top: 3px;
  color: var(--surface);
  font-size: 20px;
  font-weight: 750;
  line-height: 1.05;
}

.live-pill {
  padding: 5px 8px;
  color: var(--lime-ink);
  background: var(--lime);
  border-radius: 999px;
  font-size: 10px;
  font-weight: 850;
  letter-spacing: 0.06em;
}

.content-grid {
  display: grid;
  grid-template-columns: 1fr 1.16fr;
  gap: 12px;
  padding: 12px 16px;
}

.car-card,
.dispatch-card {
  box-sizing: border-box;
  border: 1px solid var(--line);
  border-radius: 12px;
}

.car-card {
  padding: 10px;
  background: var(--soft);
}

.car-header,
.dispatch-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.car-header h2,
.dispatch-header h2 {
  font-size: 12px;
  font-weight: 800;
}

.door-status {
  padding: 3px 5px;
  color: var(--amber-ink);
  background: var(--amber);
  border-radius: 4px;
  font-size: 8px;
  font-weight: 850;
  letter-spacing: 0.05em;
}

.floor-display {
  display: grid;
  grid-template-columns: 1fr auto;
  align-items: end;
  margin-top: 8px;
  padding: 8px 10px;
  color: var(--surface);
  background: var(--navy);
  border-radius: 8px;
}

.floor-display span,
.floor-display small {
  color: var(--line);
  font-size: 9px;
  font-weight: 650;
}

.floor-display strong {
  grid-row: span 2;
  color: var(--lime);
  font-size: 31px;
  font-weight: 800;
  line-height: 0.9;
}

.floor-display small {
  margin-top: 4px;
}

.stop-list,
.route-list {
  padding: 0;
  margin: 0;
  list-style: none;
}

.stop-list {
  display: grid;
  gap: 6px;
  margin-top: 9px;
}

.stop-list li {
  display: grid;
  grid-template-columns: 8px 18px 1fr;
  align-items: center;
  gap: 5px;
  color: var(--muted);
  font-size: 10px;
}

.stop-list b {
  color: var(--ink);
  font-size: 11px;
}

.stop-dot,
.signal-dot {
  display: inline-block;
  box-sizing: border-box;
  width: 7px;
  height: 7px;
  border: 1px solid var(--muted);
  border-radius: 50%;
}

.stop-dot.active {
  border-color: var(--green);
  background: var(--green);
}

.dispatch-card {
  padding: 10px 11px;
}

.dispatch-header span {
  color: var(--muted);
  font-size: 10px;
  font-weight: 700;
}

.route-list {
  margin-top: 7px;
  border-top: 1px solid var(--line);
}

.route-list li {
  display: grid;
  grid-template-columns: 25px 1fr auto;
  align-items: center;
  gap: 7px;
  min-height: 25px;
  border-bottom: 1px solid var(--line);
  color: var(--muted);
  font-size: 10px;
}

.route-floor {
  padding: 3px 0;
  color: var(--navy);
  background: var(--soft);
  border-radius: 4px;
  font-size: 10px;
  font-weight: 850;
  text-align: center;
}

.route-list time {
  color: var(--ink);
  font-size: 9px;
  font-weight: 750;
}

.arrival-note {
  margin-top: 8px;
  color: var(--muted);
  font-size: 10px;
}

.arrival-note span,
.arrival-note b {
  color: var(--green);
  font-weight: 850;
}

.panel-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 9px 16px;
  border-top: 1px solid var(--line);
}

.panel-footer p {
  display: flex;
  align-items: center;
  gap: 6px;
  color: var(--muted);
  font-size: 10px;
  font-weight: 650;
}

.signal-dot {
  border-color: var(--green);
  background: var(--green);
}

.panel-footer button {
  padding: 6px 10px;
  color: var(--surface);
  background: var(--navy);
  border: 0;
  border-radius: 6px;
  font-size: 10px;
  font-weight: 800;
}

